BEGIN;

-- Require the established billing tables instead of inventing or resetting client balances.
DO $$
DECLARE v_column TEXT;
BEGIN
  IF to_regclass('legal_ai_clients') IS NULL OR to_regclass('legal_ai_requests') IS NULL THEN
    RAISE EXCEPTION 'Existing billing tables are missing. Run the original table setup first.';
  END IF;
  FOREACH v_column IN ARRAY ARRAY['channel','session_name','chat_id','free_answers_used',
    'free_answers_reserved','is_exempt','paid_access','force_payment','updated_at'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid='legal_ai_clients'::regclass
      AND attname=v_column AND NOT attisdropped) THEN
      RAISE EXCEPTION 'Missing legal_ai_clients column: %', v_column;
    END IF;
  END LOOP;
END $$;

CREATE TABLE IF NOT EXISTS legal_ai_requests_v2 (
  channel TEXT NOT NULL,
  session_name TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  message_id TEXT NOT NULL,
  status TEXT NOT NULL,
  charge_free BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (channel, session_name, message_id)
);
CREATE INDEX IF NOT EXISTS legal_ai_requests_v2_client_pending
  ON legal_ai_requests_v2(channel, session_name, chat_id, status);

-- Carry forward deduplication and pending reservations. Counters remain in the original clients table.
INSERT INTO legal_ai_requests_v2
  (channel, session_name, chat_id, message_id, status, charge_free, updated_at)
SELECT channel, session_name, chat_id, message_id, status, COALESCE(charge_free,FALSE), updated_at
FROM legal_ai_requests
ON CONFLICT (channel, session_name, message_id) DO NOTHING;

CREATE OR REPLACE FUNCTION legal_ai_reserve_question_v2(p_input JSONB)
RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE
  v_channel TEXT := p_input->>'channel';
  v_session TEXT := p_input->>'sessionName';
  v_chat TEXT := p_input->>'billingChatId';
  v_message TEXT := p_input->>'messageId';
  v_client legal_ai_clients%ROWTYPE;
  v_request legal_ai_requests_v2%ROWTYPE;
  v_charge BOOLEAN;
BEGIN
  IF v_channel NOT IN ('telegram','whatsapp') OR v_channel IS NULL
     OR COALESCE(v_session,'')='' OR COALESCE(v_chat,'')=''
     OR COALESCE(v_message,'')='' THEN
    RAISE EXCEPTION 'Incomplete billing identity';
  END IF;

  -- All reservations and finishes lock the client first, then the request.
  SELECT * INTO STRICT v_client FROM legal_ai_clients
  WHERE channel=v_channel AND session_name=v_session AND chat_id=v_chat FOR UPDATE;

  SELECT * INTO v_request FROM legal_ai_requests_v2
  WHERE channel=v_channel AND session_name=v_session AND message_id=v_message FOR UPDATE;
  IF FOUND AND v_request.status IN ('reserved','sent') THEN
    RETURN p_input || jsonb_build_object('client',to_jsonb(v_client),
      'billing',jsonb_build_object('allowed',FALSE,'duplicate',TRUE,'reason','duplicate'));
  END IF;

  IF COALESCE(v_client.force_payment,FALSE) OR
     (NOT COALESCE(v_client.is_exempt,FALSE) AND NOT COALESCE(v_client.paid_access,FALSE)
      AND COALESCE(v_client.free_answers_used,0)>=2) THEN
    RETURN p_input || jsonb_build_object('client',to_jsonb(v_client),
      'billing',jsonb_build_object('allowed',FALSE,'duplicate',FALSE,'reason','payment'));
  END IF;

  IF COALESCE(v_client.free_answers_reserved,0)>0 OR EXISTS (
    SELECT 1 FROM legal_ai_requests_v2 WHERE channel=v_channel AND session_name=v_session
      AND chat_id=v_chat AND status='reserved') THEN
    RETURN p_input || jsonb_build_object('client',to_jsonb(v_client),
      'billing',jsonb_build_object('allowed',FALSE,'duplicate',FALSE,'reason','processing'));
  END IF;

  v_charge := NOT COALESCE(v_client.is_exempt,FALSE) AND NOT COALESCE(v_client.paid_access,FALSE);
  INSERT INTO legal_ai_requests_v2(channel,session_name,chat_id,message_id,status,charge_free)
  VALUES(v_channel,v_session,v_chat,v_message,'reserved',v_charge)
  ON CONFLICT(channel,session_name,message_id) DO UPDATE SET
    status='reserved',charge_free=EXCLUDED.charge_free,updated_at=NOW();

  IF v_charge THEN
    UPDATE legal_ai_clients SET free_answers_reserved=COALESCE(free_answers_reserved,0)+1,
      updated_at=NOW() WHERE channel=v_channel AND session_name=v_session AND chat_id=v_chat
      RETURNING * INTO v_client;
  END IF;
  RETURN p_input || jsonb_build_object('client',to_jsonb(v_client),
    'billing',jsonb_build_object('allowed',TRUE,'duplicate',FALSE,'reason','reserved','charge_free',v_charge));
END $$;

CREATE OR REPLACE FUNCTION legal_ai_finish_question_v2(
  p_channel TEXT, p_session TEXT, p_message TEXT, p_succeeded BOOLEAN)
RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE
  v_request legal_ai_requests_v2%ROWTYPE;
  v_client legal_ai_clients%ROWTYPE;
BEGIN
  SELECT * INTO v_request FROM legal_ai_requests_v2
    WHERE channel=p_channel AND session_name=p_session AND message_id=p_message;
  IF NOT FOUND THEN RETURN jsonb_build_object('status','not_reserved'); END IF;

  SELECT * INTO STRICT v_client FROM legal_ai_clients
    WHERE channel=p_channel AND session_name=p_session AND chat_id=v_request.chat_id FOR UPDATE;
  SELECT * INTO STRICT v_request FROM legal_ai_requests_v2
    WHERE channel=p_channel AND session_name=p_session AND message_id=p_message FOR UPDATE;

  IF v_request.status='reserved' THEN
    IF v_request.charge_free THEN
      UPDATE legal_ai_clients SET
        free_answers_reserved=GREATEST(COALESCE(free_answers_reserved,0)-1,0),
        free_answers_used=COALESCE(free_answers_used,0)+CASE WHEN p_succeeded THEN 1 ELSE 0 END,
        updated_at=NOW()
      WHERE channel=p_channel AND session_name=p_session AND chat_id=v_request.chat_id
      RETURNING * INTO v_client;
    END IF;
    UPDATE legal_ai_requests_v2 SET
      status=CASE WHEN p_succeeded THEN 'sent' ELSE 'failed' END,updated_at=NOW()
    WHERE channel=p_channel AND session_name=p_session AND message_id=p_message
      RETURNING * INTO v_request;
  END IF;
  RETURN jsonb_build_object('status',v_request.status,'free_answers_used',v_client.free_answers_used,
    'free_answers_reserved',v_client.free_answers_reserved);
END $$;

COMMIT;

BEGIN;
ALTER TABLE legal_ai_clients ADD COLUMN IF NOT EXISTS human_handoff BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE legal_ai_clients ADD COLUMN IF NOT EXISTS human_pause_all BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS legal_ai_admin_tickets (
 id BIGSERIAL PRIMARY KEY, channel TEXT NOT NULL, session_name TEXT NOT NULL,
 chat_id TEXT NOT NULL, message_id TEXT NOT NULL, kind TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'pending', input JSONB NOT NULL,
 reason TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 UNIQUE(channel,session_name,chat_id,message_id,kind)
);
CREATE TABLE IF NOT EXISTS legal_ai_admin_command_log (
 session_name TEXT NOT NULL, message_id TEXT NOT NULL, action TEXT NOT NULL,
 ticket_id BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 PRIMARY KEY(session_name,message_id)
);

CREATE TABLE IF NOT EXISTS legal_ai_ticket_events (
 channel TEXT NOT NULL,session_name TEXT NOT NULL,chat_id TEXT NOT NULL,message_id TEXT NOT NULL,kind TEXT NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(channel,session_name,chat_id,message_id,kind));

CREATE OR REPLACE FUNCTION legal_ai_open_ticket(p_input JSONB,p_kind TEXT,p_reason TEXT)
RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE v_ticket legal_ai_admin_tickets%ROWTYPE; v_new BOOLEAN:=FALSE; v_update BOOLEAN:=FALSE; v_event INTEGER;
BEGIN
 IF p_kind NOT IN ('payment','receipt','human') OR p_input->>'channel' NOT IN ('whatsapp','telegram')
 OR COALESCE(p_input->>'chatId','')='' OR COALESCE(p_input->>'messageId','')='' THEN RAISE EXCEPTION 'Invalid ticket identity'; END IF;
 INSERT INTO legal_ai_clients(channel,session_name,chat_id)
 VALUES(p_input->>'channel',p_input->>'sessionName',p_input->>'chatId') ON CONFLICT(channel,session_name,chat_id) DO NOTHING;
 PERFORM 1 FROM legal_ai_clients WHERE channel=p_input->>'channel' AND session_name=p_input->>'sessionName' AND chat_id=p_input->>'chatId' FOR UPDATE;
 SELECT * INTO v_ticket FROM legal_ai_admin_tickets WHERE channel=p_input->>'channel' AND session_name=p_input->>'sessionName'
 AND chat_id=p_input->>'chatId' AND message_id=p_input->>'messageId' AND kind=p_kind;
 IF FOUND THEN
 RETURN jsonb_build_object('ticket',to_jsonb(v_ticket),'is_new',FALSE,'is_update',FALSE,'input',p_input);
 END IF;
 INSERT INTO legal_ai_ticket_events(channel,session_name,chat_id,message_id,kind)
 VALUES(p_input->>'channel',p_input->>'sessionName',p_input->>'chatId',p_input->>'messageId',p_kind)
 ON CONFLICT DO NOTHING RETURNING 1 INTO v_event;
 IF v_event IS NULL THEN RETURN jsonb_build_object('is_new',FALSE,'is_update',FALSE,'input',p_input); END IF;
 IF p_kind='human' AND COALESCE(p_input->>'caseId','')<>'' THEN
 SELECT * INTO v_ticket FROM legal_ai_admin_tickets WHERE channel=p_input->>'channel' AND session_name=p_input->>'sessionName'
 AND chat_id=p_input->>'chatId' AND kind='human' AND status='pending' AND input->>'caseId'=p_input->>'caseId'
 ORDER BY id DESC LIMIT 1 FOR UPDATE;
 IF FOUND THEN
 UPDATE legal_ai_admin_tickets SET input=p_input,reason=COALESCE(p_reason,''),updated_at=NOW() WHERE id=v_ticket.id RETURNING * INTO v_ticket;
 v_update:=TRUE;
 END IF;
 END IF;
 IF NOT v_update THEN
 INSERT INTO legal_ai_admin_tickets(channel,session_name,chat_id,message_id,kind,input,reason)
 VALUES(p_input->>'channel',p_input->>'sessionName',p_input->>'chatId',p_input->>'messageId',p_kind,p_input,COALESCE(p_reason,'')) RETURNING * INTO v_ticket;
 v_new:=TRUE;
 END IF;
 IF p_kind='human' AND NOT COALESCE((p_input->>'collectionOnly')::boolean,FALSE) THEN
 UPDATE legal_ai_clients SET human_handoff=TRUE,updated_at=NOW() WHERE channel=v_ticket.channel AND session_name=v_ticket.session_name AND chat_id=v_ticket.chat_id;
 END IF;
 RETURN jsonb_build_object('ticket',to_jsonb(v_ticket),'is_new',v_new,'is_update',v_update,'input',p_input);
END $$;

CREATE OR REPLACE FUNCTION legal_ai_admin_command(p_action TEXT,p_id BIGINT,p_text TEXT)
RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE t legal_ai_admin_tickets%ROWTYPE; resume JSONB; msg TEXT;
BEGIN
 SELECT * INTO t FROM legal_ai_admin_tickets WHERE id=p_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','missing','adminText','رقم الطلب غير موجود'); END IF;
 PERFORM 1 FROM legal_ai_clients WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id FOR UPDATE;
 SELECT * INTO STRICT t FROM legal_ai_admin_tickets WHERE id=p_id FOR UPDATE;
 IF p_action='pay' THEN
  IF t.kind NOT IN ('payment','receipt') THEN RETURN jsonb_build_object('status','invalid','adminText','هذا ليس طلب دفع'); END IF;
  IF t.status<>'pending' THEN RETURN jsonb_build_object('status','duplicate','adminText','طلب الدفع سبق التعامل معه؛ لم يُكرر التنفيذ'); END IF;
  UPDATE legal_ai_clients SET paid_access=TRUE,force_payment=FALSE,updated_at=NOW()
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id;
  SELECT input INTO resume FROM legal_ai_admin_tickets
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id
    AND kind='payment' AND status='pending' ORDER BY created_at DESC,id DESC LIMIT 1;
  UPDATE legal_ai_admin_tickets SET status='approved',updated_at=NOW()
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id
    AND kind IN ('payment','receipt') AND status='pending';
  msg:='اعتمد المحامي الدفع. '||CASE WHEN resume IS NOT NULL THEN 'هنستكمل طلبك المحفوظ الآن.' ELSE 'تقدر تبعت طلبك لاستكمال المتابعة.' END;
 ELSIF p_action='reject' THEN
  IF t.kind NOT IN ('payment','receipt') OR t.status<>'pending' THEN
   RETURN jsonb_build_object('status','invalid','adminText','طلب الدفع غير معلق'); END IF;
  UPDATE legal_ai_admin_tickets SET status='rejected',updated_at=NOW() WHERE id=p_id;
  msg:='لم يتم اعتماد الدفع. تواصل مع المكتب لتوضيح بيانات التحويل.';
 ELSIF p_action='human' THEN
  UPDATE legal_ai_clients SET human_pause_all=TRUE,human_handoff=TRUE,updated_at=NOW()
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id;
  msg:='المحادثة بقت في متابعة المحامي. الرد القادم سيكون من شخص بشري.';
 ELSIF p_action='resume' THEN
  UPDATE legal_ai_clients SET human_pause_all=FALSE,human_handoff=FALSE,updated_at=NOW()
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id;
  UPDATE legal_ai_admin_tickets SET status='resolved',updated_at=NOW()
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id AND kind='human';
  msg:='رجع الرد الآلي للمحادثة. تقدر تبعت طلبك التالي.';
 ELSIF p_action='stop' THEN
  UPDATE legal_ai_clients SET paid_access=FALSE,force_payment=TRUE,updated_at=NOW()
   WHERE channel=t.channel AND session_name=t.session_name AND chat_id=t.chat_id;
  msg:='تم إيقاف المتابعة المدفوعة لحين اعتماد جديد من المكتب.';
 ELSIF p_action='reply' THEN
  IF COALESCE(BTRIM(p_text),'')='' THEN RETURN jsonb_build_object('status','invalid','adminText','اكتب نص الرد بعد رقم الطلب'); END IF;
  msg:=p_text;
 ELSE RETURN jsonb_build_object('status','invalid','adminText','أمر غير مدعوم');
 END IF;
 RETURN jsonb_build_object('status','ok','adminText','تم تنفيذ الأمر للطلب '||p_id,
  'channel',t.channel,'sessionName',t.session_name,'chatId',t.chat_id,'replyText',msg,'resumeInput',resume);
END $$;
COMMIT;

BEGIN;
CREATE TABLE IF NOT EXISTS legal_ai_cases (
 id BIGSERIAL PRIMARY KEY, case_ref TEXT UNIQUE, channel TEXT NOT NULL,
 session_name TEXT NOT NULL, chat_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active',
 category TEXT NOT NULL DEFAULT 'unclear', analysis JSONB NOT NULL DEFAULT '{}',
 clarification_streak INTEGER NOT NULL DEFAULT 0,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS legal_ai_cases_client ON legal_ai_cases(channel,session_name,chat_id,status);
CREATE TABLE IF NOT EXISTS legal_ai_case_messages (
 id BIGSERIAL PRIMARY KEY, case_id BIGINT NOT NULL REFERENCES legal_ai_cases(id),
 channel TEXT NOT NULL, session_name TEXT NOT NULL, chat_id TEXT NOT NULL,
 message_id TEXT NOT NULL, direction TEXT NOT NULL, text TEXT NOT NULL DEFAULT '',
 metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 UNIQUE(channel,session_name,chat_id,message_id,direction)
);
CREATE TABLE IF NOT EXISTS legal_ai_client_documents (
 id BIGSERIAL PRIMARY KEY, case_id BIGINT REFERENCES legal_ai_cases(id), channel TEXT NOT NULL,
 session_name TEXT NOT NULL, chat_id TEXT NOT NULL, message_id TEXT NOT NULL,
 filename TEXT NOT NULL, mime_type TEXT NOT NULL, data BYTEA NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(channel,session_name,chat_id,message_id)
);
CREATE TABLE IF NOT EXISTS legal_ai_source_documents (
 id BIGSERIAL PRIMARY KEY, source_url TEXT NOT NULL, content_hash TEXT NOT NULL,
 category TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'unknown',
 issuing_authority TEXT NOT NULL DEFAULT '', document_number TEXT NOT NULL DEFAULT '',
 publication_date TEXT, issued_date TEXT, effective_date TEXT,
 verification_level TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', practical_effect TEXT NOT NULL DEFAULT '',
 source_text TEXT NOT NULL DEFAULT '', original_pdf BYTEA, extracted JSONB NOT NULL DEFAULT '{}',
 first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), last_checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 last_notified_at TIMESTAMPTZ, UNIQUE(source_url,content_hash)
);
CREATE TABLE IF NOT EXISTS legal_ai_research_runs (
 id BIGSERIAL PRIMARY KEY, job_id TEXT NOT NULL, mode TEXT NOT NULL, category TEXT NOT NULL,
 query TEXT NOT NULL, success BOOLEAN NOT NULL, coverage JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS legal_ai_monitor_state (
 category TEXT PRIMARY KEY, last_attempt_at TIMESTAMPTZ, last_success_at TIMESTAMPTZ,
 last_failure_alert_at TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS legal_ai_research_parts (
 job_id TEXT NOT NULL, evidence_key TEXT NOT NULL, payload JSONB NOT NULL,
 PRIMARY KEY(job_id,evidence_key)
);
CREATE TABLE IF NOT EXISTS legal_ai_research_completion (
 job_id TEXT PRIMARY KEY, dispatched BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE OR REPLACE FUNCTION legal_ai_case_intake(p JSONB) RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE v_case legal_ai_cases%ROWTYPE; v_existing BIGINT; v_history JSONB;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext((p->>'channel')||':'||(p->>'sessionName')||':'||(p->>'chatId')));
 SELECT case_id INTO v_existing FROM legal_ai_case_messages
  WHERE channel=p->>'channel' AND session_name=p->>'sessionName' AND chat_id=p->>'chatId'
   AND message_id=p->>'messageId' AND direction='inbound';
 IF FOUND THEN SELECT * INTO STRICT v_case FROM legal_ai_cases WHERE id=v_existing;
 ELSIF COALESCE(p->>'requestedCaseRef','')<>'' THEN
  SELECT * INTO STRICT v_case FROM legal_ai_cases WHERE case_ref=p->>'requestedCaseRef'
   AND channel=p->>'channel' AND session_name=p->>'sessionName' AND chat_id=p->>'chatId';
 ELSE
  IF NOT COALESCE((p->>'startNewCase')::boolean,FALSE) THEN
   SELECT * INTO v_case FROM legal_ai_cases WHERE channel=p->>'channel'
    AND session_name=p->>'sessionName' AND chat_id=p->>'chatId' AND status<>'closed'
    ORDER BY updated_at DESC,id DESC LIMIT 1;
  END IF;
  IF v_case.id IS NULL THEN
   INSERT INTO legal_ai_cases(channel,session_name,chat_id)
   VALUES(p->>'channel',p->>'sessionName',p->>'chatId') RETURNING * INTO v_case;
   UPDATE legal_ai_cases SET case_ref='LC-'||to_char(created_at,'YYYY')||'-'||id
    WHERE id=v_case.id RETURNING * INTO v_case;
  END IF;
 END IF;
 INSERT INTO legal_ai_case_messages(case_id,channel,session_name,chat_id,message_id,direction,text,metadata)
 VALUES(v_case.id,p->>'channel',p->>'sessionName',p->>'chatId',p->>'messageId','inbound',COALESCE(p->>'chatInput',''),
  jsonb_build_object('file_name',p->>'originalFileName','mime_type',p->>'mimeType','extraction_needs_review',p->'extractionNeedsReview'))
 ON CONFLICT DO NOTHING;
 UPDATE legal_ai_client_documents SET case_id=v_case.id WHERE channel=p->>'channel'
  AND session_name=p->>'sessionName' AND chat_id=p->>'chatId' AND message_id=p->>'messageId';
 SELECT COALESCE(jsonb_agg(to_jsonb(h) ORDER BY h.id),'[]') INTO v_history FROM (
  SELECT id,direction,text,metadata,created_at FROM legal_ai_case_messages
   WHERE case_id=v_case.id ORDER BY id DESC LIMIT 30) h;
 UPDATE legal_ai_cases SET updated_at=NOW() WHERE id=v_case.id;
 RETURN p||jsonb_build_object('caseId',v_case.id,'caseRef',v_case.case_ref,'priorCaseAnalysis',v_case.analysis,
  'caseCategory',v_case.category,'clarificationStreak',v_case.clarification_streak,'caseHistory',v_history);
END $$;

CREATE OR REPLACE FUNCTION legal_ai_save_case_analysis(p JSONB) RETURNS JSONB LANGUAGE plpgsql AS $$
BEGIN
 UPDATE legal_ai_cases SET analysis=COALESCE(p->'caseAnalysis','{}'),
  category=COALESCE(p->'caseAnalysis'->>'category','unclear'),updated_at=NOW() WHERE id=(p->>'caseId')::bigint;
 RETURN p;
END $$;

CREATE OR REPLACE FUNCTION legal_ai_log_case_reply(p JSONB,p_text TEXT,p_mode TEXT) RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE v_insert BIGINT;
BEGIN
 IF COALESCE(p->>'caseId','')='' THEN RETURN jsonb_build_object('status','no_case'); END IF;
 INSERT INTO legal_ai_case_messages(case_id,channel,session_name,chat_id,message_id,direction,text,metadata)
 VALUES((p->>'caseId')::bigint,p->>'channel',p->>'sessionName',p->>'chatId',p->>'messageId','outbound',COALESCE(p_text,''),jsonb_build_object('mode',p_mode))
 ON CONFLICT DO NOTHING RETURNING id INTO v_insert;
 IF v_insert IS NOT NULL THEN
  UPDATE legal_ai_cases SET clarification_streak=CASE WHEN p_mode='clarify' THEN clarification_streak+1 ELSE 0 END,
   status=CASE WHEN p_mode='human' THEN 'human' ELSE status END,updated_at=NOW() WHERE id=(p->>'caseId')::bigint;
 END IF;
 RETURN jsonb_build_object('status','logged');
END $$;

CREATE OR REPLACE FUNCTION legal_ai_store_research(p_batches JSONB) RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE b JSONB; d JSONB; new_id BIGINT; digest TEXT; result JSONB:='[]'; docs JSONB;
 alert_rows JSONB; v_category TEXT; is_ok BOOLEAN; failure_notice BOOLEAN; changed_ids BIGINT[];
 v_count INTEGER; v_done BOOLEAN; v_job TEXT; v_parts JSONB;
BEGIN
 FOR b IN SELECT value FROM jsonb_array_elements(p_batches) LOOP
  v_job:=b->'job'->>'jobId';
  PERFORM pg_advisory_xact_lock(hashtext(v_job));
  INSERT INTO legal_ai_research_completion(job_id) VALUES(v_job) ON CONFLICT DO NOTHING;
  SELECT dispatched INTO v_done FROM legal_ai_research_completion WHERE job_id=v_job FOR UPDATE;
  IF v_done THEN CONTINUE; END IF;
  FOR d IN SELECT value FROM jsonb_array_elements(COALESCE(b->'parts','[]')) LOOP
   INSERT INTO legal_ai_research_parts(job_id,evidence_key,payload)
   VALUES(v_job,d->>'evidenceKey',d) ON CONFLICT DO NOTHING;
  END LOOP;
  SELECT COUNT(*),COALESCE(jsonb_agg(payload),'[]') INTO v_count,v_parts
   FROM legal_ai_research_parts WHERE job_id=v_job;
  IF v_count<COALESCE((b->'job'->>'expectedEvidence')::integer,1) THEN CONTINUE; END IF;
  SELECT jsonb_build_object('job',b->'job',
   'documents',COALESCE(jsonb_agg(p->'document') FILTER(WHERE p ? 'document'),'[]'),
   'success',BOOL_AND(COALESCE((p->>'success')::boolean,FALSE)),
   'coverage',jsonb_build_object('failures',COALESCE(jsonb_agg(p->>'failure') FILTER(WHERE COALESCE(p->>'failure','')<>''),'[]'),
    'notes',COALESCE(jsonb_agg(p->'coverageNotes'),'[]'),'retrieved',COUNT(*) FILTER(WHERE p ? 'document')))
   INTO b FROM jsonb_array_elements(v_parts) p;
  UPDATE legal_ai_research_completion SET dispatched=TRUE WHERE job_id=v_job;
  v_category:=b->'job'->>'category'; changed_ids:=ARRAY[]::BIGINT[];
  FOR d IN SELECT value FROM jsonb_array_elements(COALESCE(b->'documents','[]')) LOOP
   IF COALESCE(d->>'sourceUrl','')='' OR COALESCE(d->>'sourceText','')='' THEN CONTINUE; END IF;
   digest:=md5(COALESCE(d->>'sourceText','')||COALESCE(d->>'sourcePdfBase64',''));
   INSERT INTO legal_ai_source_documents(source_url,content_hash,category,title,kind,issuing_authority,document_number,
    publication_date,issued_date,effective_date,verification_level,summary,practical_effect,source_text,original_pdf,extracted)
   VALUES(d->>'sourceUrl',digest,v_category,COALESCE(d->>'title',''),COALESCE(d->>'kind','unknown'),
    COALESCE(d->>'issuingAuthority',''),COALESCE(d->>'documentNumber',''),d->>'publicationDate',d->>'issuedDate',d->>'effectiveDate',
    d->>'verificationLevel',COALESCE(d->>'summary',''),COALESCE(d->>'practicalEffect',''),d->>'sourceText',
    CASE WHEN COALESCE(d->>'sourcePdfBase64','')<>'' THEN decode(d->>'sourcePdfBase64','base64') ELSE NULL END,d-'sourcePdfBase64'-'sourceText')
   ON CONFLICT(source_url,content_hash) DO UPDATE SET last_checked_at=NOW() RETURNING id INTO new_id;
   changed_ids:=array_append(changed_ids,new_id);
  END LOOP;
  is_ok:=COALESCE((b->>'success')::boolean,FALSE);
  INSERT INTO legal_ai_research_runs(job_id,mode,category,query,success,coverage)
  VALUES(b->'job'->>'jobId',b->'job'->>'mode',v_category,b->'job'->>'query',is_ok,COALESCE(b->'coverage','{}'));
  INSERT INTO legal_ai_monitor_state(category,last_attempt_at,last_success_at)
  VALUES(v_category,NOW(),CASE WHEN is_ok THEN NOW() ELSE NULL END)
  ON CONFLICT(category) DO UPDATE SET last_attempt_at=NOW(),last_success_at=CASE WHEN is_ok THEN NOW() ELSE legal_ai_monitor_state.last_success_at END;
  SELECT COALESCE(jsonb_agg((to_jsonb(s) - 'original_pdf' - 'source_text') || jsonb_build_object('evidence_text',left(s.source_text,40000),'evidence_limited',length(s.source_text)>40000) ORDER BY s.last_checked_at DESC),'[]') INTO docs FROM (
   SELECT * FROM legal_ai_source_documents WHERE id=ANY(changed_ids) AND verification_level='official_text_retrieved'
    ORDER BY last_checked_at DESC LIMIT 8) s;
  SELECT COALESCE(jsonb_agg(to_jsonb(s)-'original_pdf'-'source_text'),'[]') INTO alert_rows FROM (
   SELECT s.* FROM legal_ai_source_documents s WHERE id=ANY(changed_ids) AND last_notified_at IS NULL
    AND verification_level IN ('official_text_retrieved','official_notice_retrieved')
    AND publication_date ~ '^\d{4}-\d{2}-\d{2}$'
    AND publication_date::date >= CURRENT_DATE-7 AND publication_date::date<=CURRENT_DATE
    ORDER BY first_seen_at DESC LIMIT 6) s;
  failure_notice:=FALSE;
  IF b->'job'->>'mode'='monitor' AND NOT is_ok THEN
   UPDATE legal_ai_monitor_state SET last_failure_alert_at=NOW() WHERE legal_ai_monitor_state.category=v_category
    AND (last_failure_alert_at IS NULL OR last_failure_alert_at<NOW()-INTERVAL '24 hours');
   failure_notice:=FOUND;
  END IF;
  result:=result||jsonb_build_array(jsonb_build_object('job',b->'job','documents',docs,
    'alerts',alert_rows,'success',is_ok,'coverage',b->'coverage','failureNotice',failure_notice));
 END LOOP;
 RETURN result;
END $$;
COMMIT;

BEGIN;
CREATE TABLE IF NOT EXISTS legal_ai_fast_receipts (
