 if (!['telegram','whatsapp'].includes(j.channel) || !j.chatId || !j.messageId)
   throw new Error('بيانات القناة أو العميل أو الرسالة ناقصة');
 const mime=String(file?.mimeType || '').toLowerCase().split(';')[0].trim();
 const ext=String(file?.fileName || '').toLowerCase().split('.').pop();
 let fileKind='text';
 if (j.hasMedia) {
   if (!file) fileKind='unsupported';
   else if (mime==='application/pdf' || ext==='pdf') fileKind='pdf';
   else if (mime.startsWith('image/') || ['png','jpg','jpeg','webp','gif'].includes(ext)) fileKind='image';
   else if (mime.startsWith('audio/') || (mime==='application/ogg' && ext==='ogg')) fileKind='audio';
   else if (['application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'].includes(mime) || ['doc','docx'].includes(ext)) fileKind='word';
   else if (mime==='text/plain' || ext==='txt') fileKind='plain_text';
   else fileKind='unsupported';
 }
 return {json:{...j,fileKind,mimeType:mime,originalFileName:file?.fileName || '',
   originalChatInput:String(j.chatInput || '').trim(),
   billingChatId:String(j.chatId)},...(file ? {binary:{data:file}}:{}),pairedItem:{item:index}};
});

