const hook={...(relevant[0]||{}),url:target,events:['message.any']};
hook.customHeaders=(hook.customHeaders||[]).filter(h=>String(h.name).toLowerCase()!=='x-legal-webhook-token');
hook.customHeaders.push({name:'X-Legal-Webhook-Token',value:"cpIvIMuNFWC0e1YPi0zvAZhCVMAdXXwdIT24YLnt4H_LNf2n63mNrg"});
