 if (!own&&!incoming) continue;
 const quotedReply=Boolean(p.replyTo?.id)&&Boolean(String(p.body||'').trim());
 if (own && !quotedReply && !/^(?:\/?(?:دفع|موافق|موافقة|رفض|بشري|بشرى|عودة|عوده|رد|ايقاف|إيقاف|مساعدة|مساعده|ملف|تفاصيل|pay|reject|human|resume|reply|stop|help))(?:\s|$)/i.test(String(p.body||'').trim())) continue;
 result.push({json:{...j,eventRoute:own?'admin':'client',ownerChatId:"201120399998@c.us"},pairedItem:{item:i}});
}
return result;

