 j.ticket.kind==='human'?'النقطة دي محتاجة رأي المحامي. هكمل معاك تجميع التفاصيل والأوراق هنا عشان يراجع الموضوع كاملًا.':j.replyText;
 return {json:{...j,replyText},pairedItem:{item:i}};
}).filter(x=>x.json.replyText);

const j=$input.first().json;
