const asksHuman=/(?:عايز|عاوز|اريد|محتاج|ممكن).{0,25}(?:اتكلم|اكلم|اتواصل|تواصل|حديث).{0,25}(?:محامي|المحامي|محامى|بشر|انسان|شخص)|(?:حولني|حولنى|حولوني|حولونى).{0,25}(?:محامي|المحامي|محامى|بشر)|(?:طلب\s*محامي|طلب\s*محامى|speak\s+to\s+(?:a\s+)?(?:lawyer|human))|^(?:عايز|عاوز|اريد|محتاج)\s+(?:محامي|محامى|بشر)(?:\s|$)/i.test(text);
return [{json:{...j,needsHuman:j.client?.human_pause_all===true||asksHuman,factualOnly:j.client?.human_handoff===true&&Boolean(j.client?.review_ticket),hardHandoff:j.client?.human_pause_all===true||asksHuman,
 humanReason:j.client?.human_pause_all===true?'المحامي أوقف المساعد يدويًا':'العميل طلب التحدث إلى محامي'},pairedItem:{item:0}}];

