const reportText=typeof d.report_text==='string'?d.report_text:'';
if(reportText.length>60000)throw Error('التقرير يتجاوز حجم التسليم');
return [{json:{...base,mode,attachReport:mode==='reply'&&Boolean(reportText),reportText:mode==='reply'?reportText:'',reportTitle:String(d.report_title||'تقرير قانوني'),output:mode==='human'?'':d.reply.trim()+suffix,handoffSummary:String(d.summary||base.caseAnalysis?.summary||''),humanReason:reason||'تحتاج المسألة لتقدير المحامي بعد فحص الوقائع'},pairedItem:{item:0}}];

const out=[];
for (let i=0;i<$input.all().length;i++) {
 const item=$input.all()[i],input={...item.json}; delete input.headers;
 let base64='';
 if(item.binary?.data){
  const data=await this.helpers.getBinaryDataBuffer(i,'data');
  if(data.length>20*1024*1024) throw new Error('المرفق يتجاوز حد الأرشفة: 20 ميجابايت');
