 const date=s=>{if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('تاريخ غير محدد بدقة');const dt=new Date(s+'T12:00:00Z');if(!Number.isFinite(+dt)||dt.toISOString().slice(0,10)!==s)throw Error('تاريخ غير صحيح');return dt;};
 const add=(dt,num)=>{const v=new Date(dt);v.setUTCDate(v.getUTCDate()+num);return v;},iso=dt=>dt.toISOString().slice(0,10);
 for(const key of ['event_confirmed','exclude_event_day','applicability_confirmed','no_suspension_or_interruption','distance_not_applicable','holiday_calendar_complete','extension_rule_confirmed'])if(p[key]!==true)throw Error('ميعاد غير متحقق: '+key);
 if(p.unit!=='days'||!Number.isInteger(p.duration_days)||p.duration_days<1||p.duration_days>366||p.distance_days!==0||!Array.isArray(p.assumptions)||p.assumptions.length)throw Error('هذه الحالة تحتاج حسابًا متخصصًا');
