 if(!Array.isArray(evs))throw Error('أدلة قواعد الميعاد مفقودة');
 for(const purpose of ['duration','start','extension','calendar','distance']){
  const valid=evs.some(e=>{
   const doc=docs.find(x=>x.source_url===e.source_url),q=norm(e.quote);
   if(e.purpose!==purpose||!doc||doc.evidence_limited===true||q.length<15||!norm(doc.evidence_text).includes(q))return false;
   if(purpose==='duration'){
    const digits=s=>String(s||'').replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776));
    const numeric=norm(e.numeric_duration_text),tokens=digits(numeric).match(/\d+/g)||[];
    return numeric.length>=3&&q.includes(numeric)&&tokens.length===1&&Number(tokens[0])===p.duration_days&&/(?:يوم|يوما|يومًا|أيام|ايام|days?)/i.test(numeric);
   }return true;
  });if(!valid)throw Error('قاعدة ميعاد بلا دليل حرفي متحقق: '+purpose);
 }
 if(!Array.isArray(p.closed_dates)||!Array.isArray(p.weekly_closed_days)||p.weekly_closed_days.some(x=>!Number.isInteger(x)||x<0||x>6)||p.weekly_closed_days.length>3)throw Error('تقويم العطلات غير صالح');
 const closed=new Set(p.closed_dates.map(x=>iso(date(x))));
